    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: individuel samlet vurdering på velbeskrevet, lægefagligt dokumenteret grundlag, funktionsnedsættelsen og dens påvirkning af dagligt funktionsniveau, behandling med effekt, restsymptomer, bivirkninger og rimelig medvirken, samt varighed, gentagne perioder og tilbagefaldsrisiko. Det understøttende element om, at en diagnose ikke i sig selv er afgørende, mangler, men det er ikke kritisk."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad Udbetaling Danmark lægger vægt på ved vurderingen af sværhedsgraden, uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse, paragraf eller vejledningsafsnit. Det er kun almindelig tekst uden henvisninger."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildens gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle påstande genfindes i vejledningens afsnit 3.4.1.2. Svaret tilføjer ingen ny regel, betingelse, tærskel eller myndighed."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "'blandt andet' markerer, at listen er illustrativ, og 'i rimeligt omfang' er bevaret for medvirken til behandling. Opregningen fremstilles ikke som kumulative betingelser. Svaret siger ikke eksplicit, at momenterne ikke er selvstændige betingelser, men de præsenteres som momenter i en samlet vurdering."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: først rammen for en individuel samlet vurdering på lægefagligt grundlag, derefter momenterne i vurderingen. Ingen modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'skal være velbeskrevet og lægefagligt dokumenteret' svarer til vejledningen, og 'lægges der blandt andet vægt på' gengiver 'indgår f.eks.' uden at gøre skønnet absolut. Ingen modalitetsfejl."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "partial",
      "reason": "Svaret angiver, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, og dækker momentlisten fra gold-teksten. Det udelader gold-tekstens eksempler (hovedpine, kronisk tarmsygdom), at restsymptomer kan opfylde sværhedskriteriet trods behandlingseffekt, og at det er styrelsen, der vurderer, om der er meget betydelige begrænsninger i erhvervsevnen."
    }
  },
  "overall_notes": "Indholdsmæssigt korrekt og komplet i forhold til rubrikkens kritiske elementer, men uden kildeangivelse. Derfor C04 not_met og C05 og C06 not_assessable. Det understøttende element om, at diagnosen ikke alene afgør sværhedsgraden, mangler."
